(() => {
  const script = document.currentScript;
  const base = new URL('../../', script.src);
  const product = script.dataset.product || 'zrain-ecosystem';
  const label = script.dataset.label || 'Ecosystem';
  const logo = new URL('zrain-mascot.png', base).href;
  const community = new URL('https://zrain-community.web.app/product.html');
  community.searchParams.set('product', product);
  const css = document.createElement('link');
  css.rel = 'stylesheet';
  css.href = new URL('layout.css?rev=chrome-3', script.src).href;
  document.head.append(css);
  const iconGitHub='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 .85A11.15 11.15 0 0 0 8.48 22.6c.56.1.76-.24.76-.54v-2.08c-3.1.68-3.76-1.31-3.76-1.31-.51-1.3-1.25-1.65-1.25-1.65-1.01-.69.08-.67.08-.67 1.12.08 1.7 1.15 1.7 1.15 1 1.7 2.62 1.21 3.26.92.1-.72.39-1.21.71-1.49-2.47-.28-5.06-1.24-5.06-5.51 0-1.22.44-2.21 1.15-2.99-.12-.28-.5-1.42.11-2.95 0 0 .94-.3 3.06 1.14A10.68 10.68 0 0 1 12 6.32c.95 0 1.9.13 2.79.38 2.12-1.44 3.05-1.14 3.05-1.14.61 1.53.23 2.67.11 2.95.72.78 1.15 1.77 1.15 2.99 0 4.28-2.59 5.22-5.07 5.5.4.35.75 1.03.75 2.07v3c0 .3.2.65.77.54A11.15 11.15 0 0 0 12 .85Z"/></svg>';
const iconEmail='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 7 9-7"/></svg>';
const iconCommunity='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5c-1.1 0-2.1-.2-3-.6L4 20l1.6-5.2a7.5 7.5 0 1 1 14.4-3.3Z"/><path d="M9 11.5h7m-7 3h4"/></svg>';
  function mountZrainContactLinks({container,openCommunity,githubUrl='https://github.com/zrain03',email='zrain.dev@gmail.com',document:providedDocument}={}){
  if(!container?.append)throw new TypeError('Zrain contact links require a container.');
  if(typeof openCommunity!=='function')throw new TypeError('Zrain contact links require a product-specific Community action.');
  const doc=providedDocument||container.ownerDocument;
  const nav=doc.createElement('nav');nav.className='zr-compact-contact';nav.setAttribute('aria-label','Zrain contact');
  const github=doc.createElement('a');github.href=githubUrl;github.rel='noopener noreferrer';github.target='_blank';github.innerHTML=iconGitHub+'<span><strong>GitHub</strong><small>zrain03</small></span>';github.setAttribute('aria-label','Open Zrain GitHub');
  const mail=doc.createElement('a');mail.href='mailto:'+email;mail.innerHTML=iconEmail+'<span><strong>Email</strong><small>'+email+'</small></span>';mail.setAttribute('aria-label','Email Zrain');
  const community=doc.createElement('button');community.type='button';community.innerHTML=iconCommunity+'<span><strong>Community</strong><small>Leave a note</small></span>';community.setAttribute('aria-label','Open product Community');
  community.addEventListener('click',openCommunity);
  nav.append(github,mail,community);container.append(nav);
  const setLanguage=lang=>{mail.querySelector('strong').textContent='Email';community.querySelector('strong').textContent='Community';community.querySelector('small').textContent='Leave a note';community.setAttribute('aria-label','Open product Community');};
  return {element:nav,setLanguage};
}

  const header = document.querySelector('[data-zrain-header]');
  if (header) {
    header.classList.add('zr-shared-header');
    const brand = document.createElement('a');
    brand.href = base.href;
    brand.innerHTML = '<img width="40" height="40" alt=""><strong>Zrain</strong><span></span>';
    brand.querySelector('img').src = logo;
    brand.querySelector('span').textContent = label;
    header.prepend(brand);
  }
  const stickerAssets = {"wave.webp":"data:image/webp;base64,","working.webp":"data:image/webp;base64,","celebrate.webp":"data:image/webp;base64,","pointing.webp":"data:image/webp;base64,","walking.webp":"data:image/webp;base64,","head.webp":"data:image/webp;base64,"};
function mountZrainStickers({root,blockedTop,footer,document:providedDocument,poses=['wave','working','celebrate','pointing','walking','head']}={}){
  if(!root?.append)throw new TypeError('Zrain sticker field requires a root container.');
  const doc=providedDocument||root.ownerDocument;
  const win=doc.defaultView;
  const field=doc.createElement('div');
  field.className='zr-sticker-field';
  field.setAttribute('aria-label','Moveable Zrain mascot stickers');
  const assetSrc=pose=>stickerAssets[pose+'.webp'];
  const names={wave:'Waving',working:'Working',celebrate:'Celebrating',pointing:'Pointing',walking:'Walking',head:'Mascot head',front:'Mascot'};
  const tilts=[-9,7,-5,9,-6,6];
  const items=[];
  const clamp=(value,min,max)=>Math.max(min,Math.min(max,value));
  const apply=item=>{
    item.sticker.style.setProperty('--zr-x',item.x+'px');
    item.sticker.style.setProperty('--zr-y',item.y+'px');
  };
  const bounds=item=>({
    minX:4,
    minY:4,
    maxX:Math.max(4,field.clientWidth-item.sticker.offsetWidth-4),
    maxY:Math.max(4,field.clientHeight-item.sticker.offsetHeight-4)
  });
  const limit=(item,x,y)=>{
    const range=bounds(item);
    item.x=clamp(x,range.minX,range.maxX);
    item.y=clamp(y,range.minY,range.maxY);
    apply(item);
  };
  const topInset=()=>{
    const blocked=blockedTop||root.querySelector('.game-dock');
    if(!blocked)return 0;
    const rootRect=root.getBoundingClientRect();
    const blockedRect=blocked.getBoundingClientRect();
    return Math.max(0,Math.round(blockedRect.bottom-rootRect.top+8));
  };
  const homeYFor=item=>{
    const fieldRect=field.getBoundingClientRect();
    const footerRect=footer?.getBoundingClientRect();
    const footerTop=footerRect?footerRect.top-fieldRect.top:fieldRect.height;
    const stagger=item.index%2===0?0:8;
    return Math.max(6,Math.min(Math.max(6,field.clientHeight-item.sticker.offsetHeight-6),footerTop-item.sticker.offsetHeight-24-stagger));
  };
  function position(force=false){
    field.style.top=topInset()+'px';
    const cta=doc.querySelector('.zr-compact-cta');
    const reserved=field.clientWidth>=850&&cta
      ?Math.round(cta.getBoundingClientRect().right-field.getBoundingClientRect().left+20):10;
    items.forEach(item=>{
      const span=Math.max(20,field.clientWidth-reserved-20);
      item.homeX=Math.round(reserved+span*(item.index+0.5)/items.length);
      item.homeY=homeYFor(item);
      if(force||!item.moved){item.x=item.homeX;item.y=item.homeY;apply(item)}
      else limit(item,item.x,item.y);
    });
  }
  poses.forEach((pose,index)=>{
    const sticker=doc.createElement('button');
    sticker.type='button';sticker.className='zr-sticker';
    sticker.setAttribute('aria-label',`${names[pose]||pose} sticker. Drag to move, or use arrow keys. Double click to reset.`);
    sticker.title=(names[pose]||pose)+' · drag me!';
    sticker.dataset.pose=pose;
    sticker.style.setProperty('--zr-tilt',`${tilts[index%tilts.length]}deg`);
    const img=doc.createElement('img');img.src=assetSrc(pose);img.alt='';img.draggable=false;
    sticker.append(img);field.append(sticker);
    const item={sticker,index,x:0,y:0,homeX:0,homeY:0,moved:false,drag:null};items.push(item);
    sticker.addEventListener('pointerdown',e=>{
      if(e.button!==0)return;
      e.preventDefault();
      item.drag={id:e.pointerId,px:e.clientX,py:e.clientY,x:item.x,y:item.y};
      sticker.classList.add('is-dragging');
      try{sticker.setPointerCapture(e.pointerId)}catch{}
    });
    sticker.addEventListener('pointermove',e=>{
      if(!item.drag||item.drag.id!==e.pointerId)return;
      item.moved=true;
      limit(item,item.drag.x+e.clientX-item.drag.px,item.drag.y+e.clientY-item.drag.py);
    });
    const finish=()=>{item.drag=null;sticker.classList.remove('is-dragging')};
    sticker.addEventListener('pointerup',finish);
    sticker.addEventListener('pointercancel',finish);
    sticker.addEventListener('lostpointercapture',finish);
    sticker.addEventListener('keydown',e=>{
      const moves={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-9],ArrowDown:[0,9]};
      if(!(e.key in moves))return;
      e.preventDefault();e.stopPropagation();
      item.moved=true;
      const [dx,dy]=moves[e.key];limit(item,item.x+dx,item.y+dy);
    });
    sticker.addEventListener('dblclick',()=>{item.moved=false;position(false)});
  });
  root.append(field);
  position(true);
  win.requestAnimationFrame?.(()=>position(false));
  let observer=null;
  const onResize=()=>position(false);
  if(win.ResizeObserver){
    observer=new win.ResizeObserver(onResize);
    [root,footer,blockedTop].filter(Boolean).forEach(node=>observer.observe(node));
  }else win.addEventListener('resize',onResize);
  return {
    element:field,
    reset(){items.forEach(item=>{item.moved=false});position(true)},
    destroy(){observer?.disconnect();if(!observer)win.removeEventListener('resize',onResize);field.remove()}
  };
}


  const footer = document.querySelector('[data-zrain-footer]');
  if (footer) {
    const url = new URL('footer-v4514.html', script.src);
    url.searchParams.set('product', product);
    const frame = document.createElement('iframe');
    frame.title = 'Zrain footer';
    frame.style.cssText = 'display:block;width:100%;height:152px;border:0';
    window.addEventListener('message', event => {
      if (event.origin !== url.origin || event.source !== frame.contentWindow) return;
      if (event.data?.type !== 'zrain-original-footer-height') return;
      const height = event.data.height;
      if (Number.isFinite(height) && height >= 67 && height <= 400) frame.style.height = height + 'px';
    });
    frame.src = url.href;
    footer.replaceChildren(frame);
  }
})();
